// Parse FAOSTAT indicators — fix: n8n HTTP may return string
const indicators = [
  { data: $('Fetch Crop Production Index').first().json, commodity: 'Rice', metric: 'crop_production_index', unit: 'index (2014-16=100)' },
  { data: $('Fetch Food Production Index').first().json, commodity: 'Rice', metric: 'food_production_index', unit: 'index (2014-16=100)' },
  { data: $('Fetch Fertilizer Consumption').first().json, commodity: 'Rice', metric: 'fertilizer_consumption', unit: 'kg/ha arable land' }
];

const rows = [];

for (const ind of indicators) {
  try {
    let data = ind.data;
    if (typeof data.data === 'string') data = JSON.parse(data.data);
    else if (data.data) data = data.data;
    const arr = Array.isArray(data) ? data[1] : (data && data[1] ? data[1] : []);
    if (arr && Array.isArray(arr)) {
      const latest = arr.find(r => r.value !== null && r.value !== undefined);
      if (latest) {
        rows.push({
          source: 'FAOSTAT',
          commodity: ind.commodity,
          metric: ind.metric,
          value: Math.round(latest.value * 100) / 100,
          unit: ind.unit,
          period: latest.date
        });
      }
    }
  } catch (e) { /* skip */ }
}

if (rows.length === 0) {
  return [{ json: { source: 'FAOSTAT', commodity: 'Rice', metric: 'no_data', value: 0, unit: 'N/A', period: 'N/A' } }];
}

return rows.map(r => ({ json: r }));
